#!/system/bin/sh
df /sdcard 2>/dev/null | tail -1 | awk '{
  used=$3; total=$2;
  if (total > 0) pct = int(used*100/total); else pct = 0;
  bar = "";
  filled = int(pct/2);
  for (i=0; i<filled; i++) bar = bar "█";
  for (i=filled; i<50; i++) bar = bar "░";
  printf "[%s] %d%%\n", bar, pct;
  printf "%d KB usados de %d KB\n", used, total;
}'
